/**
 * Story 289: which half of a day the day screen opens on. It lives in its own
 * module because `health.routes.ts` has to validate the `?tab=` param at route
 * time — importing it from the day-detail component would pull that component
 * (and its CSS) into the boot chunk and defeat the per-route split.
 */
export const DAY_TABS = ['activity', 'nutrition'] as const;
export type DayTab = typeof DAY_TABS[number];

/** No `?tab=` means Nutrition — the tab every other entry point has always opened. */
export const DEFAULT_DAY_TAB: DayTab = 'nutrition';

function isDayTab(value: string): value is DayTab {
    return (DAY_TABS as readonly string[]).includes(value);
}

/**
 * `?tab=` → tab. Absent is the default; anything unrecognised throws, so a bad
 * URL renders the router's raw error screen instead of silently guessing a tab.
 */
export function parseDayTab(value: string | null): DayTab {
    if (value === null) return DEFAULT_DAY_TAB;
    if (!isDayTab(value)) {
        throw new Error(`Unknown day tab "${value}" — expected one of: ${DAY_TABS.join(', ')}`);
    }
    return value;
}
